import java.sql.*; import java.util.Scanner;
public class ProductJDBC { static final String URL="jdbc:mysql://localhost:3306/college",USER="root",PASSWORD="root"; static Connection getConnection()throws SQLException{return DriverManager.getConnection(URL,USER,PASSWORD);} public static void main(String[] args){Scanner sc=new Scanner(System.in);try(Connection con=getConnection()){System.out.println("1.Insert Product\n2.Retrieve Product\n3.Update Quantity\n4.Low Stock");System.out.print("Enter choice: ");int c=sc.nextInt();sc.nextLine();if(c==1){System.out.print("Product ID: ");int id=sc.nextInt();sc.nextLine();System.out.print("Product Name: ");String n=sc.nextLine();System.out.print("Price: ");double p=sc.nextDouble();System.out.print("Quantity: ");int q=sc.nextInt();try(PreparedStatement ps=con.prepareStatement("INSERT INTO Product VALUES (?, ?, ?, ?)")){ps.setInt(1,id);ps.setString(2,n);ps.setDouble(3,p);ps.setInt(4,q);ps.executeUpdate();System.out.println("Product inserted.");}}else if(c==2){System.out.print("Product ID: ");int id=sc.nextInt();try(PreparedStatement ps=con.prepareStatement("SELECT * FROM Product WHERE ProductID=?")){ps.setInt(1,id);try(ResultSet rs=ps.executeQuery()){if(rs.next())System.out.println(rs.getInt("ProductID")+" "+rs.getString("ProductName")+" "+rs.getDouble("Price")+" "+rs.getInt("Quantity"));else System.out.println("Product not found.");}}}else if(c==3){System.out.print("Product ID: ");int id=sc.nextInt();System.out.print("New Quantity: ");int q=sc.nextInt();try(PreparedStatement ps=con.prepareStatement("UPDATE Product SET Quantity=? WHERE ProductID=?")){ps.setInt(1,q);ps.setInt(2,id);ps.executeUpdate();System.out.println("Quantity updated.");}}else if(c==4){try(PreparedStatement ps=con.prepareStatement("SELECT * FROM Product WHERE Quantity < 10");ResultSet rs=ps.executeQuery()){while(rs.next())System.out.println(rs.getInt("ProductID")+" "+rs.getString("ProductName")+" "+rs.getDouble("Price")+" "+rs.getInt("Quantity"));}}}catch(SQLException e){System.out.println("Database error: "+e.getMessage());}sc.close();} }